<!doctype html><html lang="<?php echo esc_attr( get_locale() ); ?>" dir="<?php echo $invoice->rtl ? 'rtl' : 'ltr'; ?>"><head><meta charset="utf-8"><style>
@page{margin:8mm}*{box-sizing:border-box}body{margin:0;color:#202124;font:10px/1.35 DejaVu Sans,sans-serif;direction:<?php echo $invoice->rtl ? 'rtl' : 'ltr'; ?>}.top{display:flex;align-items:flex-start;justify-content:space-between;border-bottom:1px solid #8c8f94;padding-bottom:8px}.top h1{font-size:18px;margin:0}.brand{font-size:13px;font-weight:700}.grid{display:flex;gap:12px;margin:10px 0}.grid>div{flex:1}.label{font-size:8px;font-weight:700;text-transform:uppercase;color:#646970}table{border-collapse:collapse;width:100%}thead{display:table-header-group}th{border-bottom:2px solid #2c3338;text-align:start;padding:5px 4px}td{border-bottom:1px solid #ddd;padding:5px 4px;vertical-align:top}.num{text-align:end;white-space:nowrap}.meta{font-size:8px;color:#646970}.bottom{display:flex;align-items:flex-start;gap:20px;margin-top:10px}.note{flex:1}.totals{width:38%}.totals td{padding:3px 4px}.totals tr:last-child{font-size:12px;font-weight:700}.logo{max-width:100px;max-height:36px}
</style></head><body><header class="top"><div><?php if ( $invoice->store['logo_data_uri'] ) : ?><img class="logo" src="<?php echo esc_attr( $invoice->store['logo_data_uri'] ); ?>" alt=""><?php endif; ?><div class="brand"><?php echo esc_html( $invoice->store['name'] ); ?></div><?php echo esc_html( $invoice->store['address'] ); ?></div><div><h1><?php esc_html_e( 'Invoice', 'wc-invoice-printer' ); ?> #<?php echo esc_html( $invoice->order['number'] ); ?></h1><?php echo esc_html( $invoice->order['date'] ); ?> · <?php echo esc_html( $invoice->order['status'] ); ?></div></header><section class="grid"><div><span class="label"><?php esc_html_e( 'Customer', 'wc-invoice-printer' ); ?></span><br><strong><?php echo esc_html( $invoice->customer['name'] ); ?></strong> · <?php echo esc_html( $invoice->customer['company'] ); ?><br><?php echo esc_html( $invoice->customer['billing_address'] ); ?></div><div><span class="label"><?php esc_html_e( 'Payment / delivery', 'wc-invoice-printer' ); ?></span><br><?php echo esc_html( $invoice->fulfillment['payment_method'] ); ?><br><?php echo esc_html( $invoice->fulfillment['shipping_method'] ); ?></div></section><table><thead><tr><th><?php esc_html_e( 'Description', 'wc-invoice-printer' ); ?></th><th><?php esc_html_e( 'SKU', 'wc-invoice-printer' ); ?></th><th class="num"><?php esc_html_e( 'Qty', 'wc-invoice-printer' ); ?></th><th class="num"><?php esc_html_e( 'Price', 'wc-invoice-printer' ); ?></th><th class="num"><?php esc_html_e( 'Total', 'wc-invoice-printer' ); ?></th></tr></thead><tbody><?php foreach ( $invoice->items as $item ) : ?><tr><td><strong><?php echo esc_html( $item['name'] ); ?></strong><div class="meta"><?php echo esc_html( $item['variation'] ); ?></div></td><td><?php echo esc_html( $item['sku'] ); ?></td><td class="num"><?php echo esc_html( (string) $item['quantity'] ); ?></td><td class="num"><?php echo wp_kses_post( $item['unit_price'] ); ?></td><td class="num"><?php echo wp_kses_post( $item['total'] ); ?></td></tr><?php endforeach; ?></tbody></table><div class="bottom"><div class="note"><?php if ( $invoice->fulfillment['note'] ) : ?><span class="label"><?php esc_html_e( 'Note', 'wc-invoice-printer' ); ?></span><br><?php echo nl2br( esc_html( $invoice->fulfillment['note'] ) ); ?><?php endif; ?></div><table class="totals"><?php foreach ( $invoice->totals as $total ) : ?><tr><td><?php echo esc_html( $total['label'] ); ?></td><td class="num"><?php echo wp_kses_post( $total['value'] ); ?></td></tr><?php endforeach; ?></table></div></body></html>
